//! Raw bindings to the `rpi-rgb-led-matrix` C library, generated by bindgen in `build.rs`.
//!
//! Everything here is `unsafe` and C-shaped: it is only meant to be used by the
//! safe abstractions in `wrapper.rs`. This module is private to `matrix`, so the
//! rest of the app can never call the C library directly.

// The generated code follows C naming conventions and exposes the whole C API,
// so we silence the related Rust lints for this module only.
#![allow(non_upper_case_globals)]
#![allow(non_camel_case_types)]
#![allow(non_snake_case)]
#![allow(dead_code)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
